// TestIntegrationAsyncPipeline is the async-enrichment (Phase B1) AC-1 golden: it
// drives the FULL async pipeline (api -> scan -> PutItem(pending) -> Notify ->
// enrich.Queue worker pool -> tv-parser subprocess -> store) with REAL go-plugin
// subprocesses (base-scanner + tv-parser) + REAL ffprobe over a TV fixture, and
// asserts the ASYNC model that B1 inverts to: scan returns promptly with items
// status='pending', a bounded worker pool drains the tv-parser chain in the
// background, and each TV item settles with sources["tv-parser"] + _provenance +
// _view + _stages. It reuses the scan-library harness (integration_test.go:
// buildBinary/startServer/createLibrary/scanLibrary/listItems/indexByPath/
// makeMedia/mustWrite) and adds only the async-specific assertions.
//
// This is the structural successor to integration_pipeline_test.go (the Phase A
// SYNCHRONOUS golden), which asserted items were enriched AT SCAN RETURN. B1
// inverts that premise (INV-async-is-the-point): items are 'pending' at scan
// return; enrichment is observed transitioning via ?status= over a bounded poll.
//
// Skips cleanly under -short / missing ffprobe|ffmpeg (INV-skip-clean, mirroring
// integration_test.go). Expected title/season/episode are DERIVED from the fixture
// filename here (asyncDeriveShow), not magic constants.
//
// DRAIN TERMINAL: under the seeded 'tv' module config the only queueable sources
// are tv-parser (empty AuthMode, loaded) and tmdb (SERVER, NOT loaded ->
// outcomeUnavailable -> no namespace, no ledger). kinopoisk is CLIENT -> not
// queued. allSourcesTerminal counts an attempted-but-unavailable/skipped source as
// terminal-at-settle (a source that ran this pass but produced no work), so once
// tv-parser writes its namespace each TV item settles enriched -> ready
// end-to-end. A later TMDB load (B3) re-derives ready items (namespace absent +
// not in cooldown) and runs without regressing ready.
package mellifera_test

import (
	"encoding/json"
	"net/http"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

// asyncDrainTimeout bounds the poll for the worker pool to drain the TV items to
// their ready terminal (INV-poll-bounded: never an unbounded hang). 10s is far
// above the observed sub-second drain of 3 items across the default 4-worker pool.
const asyncDrainTimeout = 10 * time.Second

// asyncToken is the admin bearer token the golden drives the server with.
const asyncToken = "async-admin-token"

// TestIntegrationAsyncPipeline is the AC-1 async golden. It builds the real server
// + base-scanner + tv-parser binaries, starts the server (temp SQLite + free port
// + the queue running with default config), scans a TV fixture library, and
// asserts: AC-async (scan returns before enrichment; >=1 pending at return),
// AC-1 (TV items settle ready with sources.tv-parser + provenance + view +
// stages), AC-1 parseTV split (base parsed has no TV fields), AC-6 soft-fail (a
// corrupt file still yields an item), AC-states (?status=ready/pending filter),
// and the AC-lease observable consequences (B6: no duplicate _stages; tmdb/kinopoisk
// absent from sources).
func TestIntegrationAsyncPipeline(t *testing.T) {
	if testing.Short() {
		t.Skip("async integration test: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — skipping async AC-1 golden (INV-skip-clean)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the real media fixture AC-1 requires")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "async-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "async-base-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "async-tv-parser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "async-image-enricher", "./plugins/image-enricher")
	fixtureRoot := asyncWriteFixtures(t)

	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, asyncToken)
	client := &http.Client{Timeout: httpTimeout}
	libID := createLibrary(t, client, baseURL, asyncToken, fixtureRoot)

	res := scanLibrary(t, client, baseURL, asyncToken, libID)
	// AC-3: the scan response shape is unchanged ({library_id, discovered,
	// persisted, warnings}); 2 ffmpeg media + 1 zero-byte corrupt.mkv are persisted.
	if res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("AC-3: scan discovered=%d persisted=%d, want 3/3", res.Discovered, res.Persisted)
	}

	// AC-async: scan returned WITHOUT awaiting enrichment. Immediately after the
	// response, >=1 item is still 'pending' (the worker pool has not drained). The
	// corrupt fixture (tv-parser skips non-TV files) stays pending, so this witness
	// is non-flaky even on a very fast drain; the HTTP response itself (carrying
	// discovered/persisted, returned before this read) is the structural proof that
	// enrichment was not awaited inline.
	if pending := len(asyncItemsByStatus(t, client, baseURL, asyncToken, libID, "pending")); pending < 1 {
		t.Fatalf("AC-async: 0 pending items immediately after scan — scan blocked on enrichment")
	}

	// AC-1: bounded poll until both TV items reach the ready drain terminal.
	tvRels := []string{"Show.Name.S01E02.1080p.mkv", "Игра престолов S01E01.mkv"}
	byRel := asyncWaitForReady(t, client, baseURL, asyncToken, libID, tvRels, asyncDrainTimeout)
	// AC-1 / AC-states(b): items now reach 'ready' e2e (tv-parser namespace + tmdb
	// attempted-but-unavailable -> allSourcesTerminal -> settled). Both TV files are ready.
	ready := len(asyncItemsByStatus(t, client, baseURL, asyncToken, libID, "ready"))
	if ready != len(tvRels) {
		t.Fatalf("AC-1: %d ready items post-drain, want %d (TV items must settle enriched->ready e2e)", ready, len(tvRels))
	}

	t.Run("AC1_golden_provenance", func(t *testing.T) { asyncAssertGolden(t, byRel) })
	t.Run("AC1_parseTV_split", func(t *testing.T) { asyncAssertParseTVSplit(t, byRel) })
	t.Run("AC6_softfail_and_B6", func(t *testing.T) { asyncAssertSoftFail(t, byRel) })
	t.Run("AC_states_filter", func(t *testing.T) { asyncAssertStates(t, client, baseURL, libID) })
}

// asyncWriteFixtures builds the TV fixture tree under a temp dir: one primary
// golden TV file (with a resolution token), one Cyrillic TV file (proves non-ASCII
// titles survive the subprocess parse), and one zero-byte file that drives the
// AC-6 unprobeable soft-fail. All three are real on-disk files.
func asyncWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	makeMedia(t, filepath.Join(root, "Show.Name.S01E02.1080p.mkv"))
	makeMedia(t, filepath.Join(root, "Игра престолов S01E01.mkv"))
	mustWrite(t, filepath.Join(root, "corrupt.mkv"), nil) // zero-byte -> AC-6 soft-fail
	return root
}

// asyncWaitForReady polls the item listing until every file in rels has reached the
// 'ready' drain terminal, or the deadline passes. Bounded (INV-poll-bounded): on
// timeout it fails with the last observed per-item statuses for diagnostics.
func asyncWaitForReady(t *testing.T, c *http.Client, baseURL, token string, libID int64, rels []string, timeout time.Duration) map[string]itemDTO {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		byRel := indexByPath(t, listItems(t, c, baseURL, token, libID))
		if asyncAllReady(byRel, rels) {
			return byRel
		}
		time.Sleep(probeInterval)
	}
	byRel := indexByPath(t, listItems(t, c, baseURL, token, libID))
	t.Fatalf("async drain did not settle %v to ready within %s; last statuses: %s",
		rels, timeout, asyncStatuses(byRel))
	return byRel
}

// asyncAllReady reports whether every rel is present and status=='ready'.
func asyncAllReady(byRel map[string]itemDTO, rels []string) bool {
	for _, rel := range rels {
		it, ok := byRel[rel]
		if !ok || it.Status != "ready" {
			return false
		}
	}
	return true
}

// asyncStatuses renders the per-item statuses for a timeout diagnostic.
func asyncStatuses(byRel map[string]itemDTO) string {
	var b strings.Builder
	for rel, it := range byRel {
		b.WriteString(rel)
		b.WriteString("=")
		b.WriteString(it.Status)
		b.WriteString(" ")
	}
	return strings.TrimSpace(b.String())
}

// asyncAssertGolden asserts AC-1 for both TV fixtures: sources.tv-parser carries
// the cleaned title + season/episode (+ resolution when present), each enriched
// field has a _provenance entry naming tv-parser, _view.title is sourced, _stages
// records an ok tv-parser entry, and status is 'ready'. Cyrillic is preserved.
func asyncAssertGolden(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	asyncAssertTVItem(t, byRel, "Show.Name.S01E02.1080p.mkv", "1080p")
	asyncAssertTVItem(t, byRel, "Игра престолов S01E01.mkv", "")
}

// asyncAssertTVItem asserts the AC-1 golden contract for one TV fixture. resolution
// is the expected sources.tv-parser.resolution ("" => assert it is absent).
func asyncAssertTVItem(t *testing.T, byRel map[string]itemDTO, rel, resolution string) {
	t.Helper()
	it, ok := byRel[rel]
	if !ok {
		t.Fatalf("AC-1: %q not persisted; have %v", rel, pathsOf(byRel))
	}
	wantTitle, wantSeason, wantEpisode, ok := asyncDeriveShow(strings.TrimSuffix(filepath.Base(rel), filepath.Ext(rel)))
	if !ok {
		t.Fatalf("AC-1: fixture %q did not yield a derivable SxxExx token (test bug)", rel)
	}
	doc := parseAsyncDoc(t, it.Document)

	tv, ok := doc.Sources["tv-parser"]
	if !ok {
		t.Fatalf("AC-1: %q sources.tv-parser missing (sources=%v)", rel, doc.Sources)
	}
	if got := asyncStr(tv, "title"); got != wantTitle {
		t.Errorf("AC-1: %q sources.tv-parser.title = %q, want %q", rel, got, wantTitle)
	}
	if got := asyncInt(tv, "season"); got != wantSeason {
		t.Errorf("AC-1: %q sources.tv-parser.season = %d, want %d", rel, got, wantSeason)
	}
	if got := asyncInt(tv, "episode"); got != wantEpisode {
		t.Errorf("AC-1: %q sources.tv-parser.episode = %d, want %d", rel, got, wantEpisode)
	}
	if resolution != "" {
		if got := asyncStr(tv, "resolution"); got != resolution {
			t.Errorf("AC-1: %q sources.tv-parser.resolution = %q, want %q (stripped from title)", rel, got, resolution)
		}
	}
	// _provenance: each enriched field names tv-parser (with a non-empty version).
	for _, field := range []string{"title", "season", "episode"} {
		p, present := doc.Provenance[field]
		if !present {
			t.Errorf("AC-1: %q _provenance.%s missing", rel, field)
			continue
		}
		if got := asyncStr(p, "plugin_id"); got != "tv-parser" {
			t.Errorf("AC-1: %q _provenance.%s.plugin_id = %q, want tv-parser", rel, field, got)
		}
		if asyncStr(p, "plugin_version") == "" {
			t.Errorf("AC-1: %q _provenance.%s.plugin_version empty", rel, field)
		}
	}
	// _view.title recomputed and sourced from tv-parser.
	if v := doc.View["title"]; asyncStr(v, "value") != wantTitle || asyncStr(v, "source") != "tv-parser" {
		t.Errorf("AC-1: %q _view.title = %v, want {value:%q,source:tv-parser}", rel, doc.View["title"], wantTitle)
	}
	// _stages: tv-parser advanced the item with status ok.
	if !asyncStageHas(doc.Stages, "tv-parser", "ok") {
		t.Errorf("AC-1: %q no _stages entry {tv-parser, status:ok}; stages=%v", rel, doc.Stages)
	}
	if it.Status != "ready" {
		t.Errorf("AC-1: %q status = %q, want ready (the async drain terminal)", rel, it.Status)
	}
}

// asyncAssertParseTVSplit is the structural/negative AC-1 proof: base-scanner's
// parsed namespace is media-type-agnostic — NO TV field leaks — while the TV parse
// comes SOLELY from sources["tv-parser"]. relative_path is echoed verbatim.
func asyncAssertParseTVSplit(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, rel := range []string{"Show.Name.S01E02.1080p.mkv", "Игра престолов S01E01.mkv"} {
		it, ok := byRel[rel]
		if !ok {
			t.Fatalf("AC-1 split: %q not persisted; have %v", rel, pathsOf(byRel))
		}
		doc := parseAsyncDoc(t, it.Document)
		for _, bad := range []string{"season", "episode", "resolution", "release_group", "title"} {
			if _, leak := doc.Parsed[bad]; leak {
				t.Errorf("AC-1 split: %q parsed.%s present — TV parse must come from tv-parser only", rel, bad)
			}
		}
		if got := asyncStr(doc.Parsed, "relative_path"); got != rel {
			t.Errorf("AC-1 split: %q parsed.relative_path = %q, want %q", rel, got, rel)
		}
		if s, e := asyncInt(doc.Sources["tv-parser"], "season"), asyncInt(doc.Sources["tv-parser"], "episode"); s < 0 || e < 0 {
			t.Errorf("AC-1 split: %q sources.tv-parser missing season/episode (=%v)", rel, doc.Sources["tv-parser"])
		}
	}
}

// asyncAssertSoftFail asserts AC-6 (the corrupt file still yields an item with an
// empty ffprobe) plus the B6 observable consequences of the lease + unavailable
// source handling: no duplicate _stages entry for one item (the lease serialized
// within-item) and sources carries ONLY tv-parser (tmdb unloaded -> unavailable ->
// no namespace; kinopoisk is CLIENT -> not queued).
func asyncAssertSoftFail(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	it, ok := byRel["corrupt.mkv"]
	if !ok {
		t.Fatalf("AC-6: corrupt.mkv not persisted (an unprobeable file must still yield an item); have %v", pathsOf(byRel))
	}
	if fp := parseAsyncDoc(t, it.Document).Ffprobe; len(fp) != 0 {
		t.Errorf("AC-6: corrupt.mkv ffprobe = %d bytes, want empty (unprobeable soft-fail)", len(fp))
	}
	for _, rel := range []string{"Show.Name.S01E02.1080p.mkv", "Игра престолов S01E01.mkv", "corrupt.mkv"} {
		item, present := byRel[rel]
		if !present {
			continue // reported elsewhere
		}
		doc := parseAsyncDoc(t, item.Document)
		// B6: sources contains ONLY tv-parser (tmdb/kinopoisk produced no namespace).
		for k := range doc.Sources {
			if k != "tv-parser" {
				t.Errorf("B6: %q sources has %q (only tv-parser should be present; tmdb unavailable, kinopoisk CLIENT)", rel, k)
			}
		}
		// B6: the lease serialized within-item -> no two _stages entries share both
		// plugin_id and started_at (a within-item duplicate would mean double-processing).
		if asyncHasDupStage(doc.Stages) {
			t.Errorf("B6: %q has duplicate _stages entries (same plugin_id+started_at); stages=%v", rel, doc.Stages)
		}
	}
}

// asyncAssertStates asserts AC-states over HTTP via the unchanged ?status=
// passthrough (S9): post-drain, ?status=ready returns exactly the two TV items,
// and ?status=pending returns the corrupt item (tv-parser skips non-TV files).
func asyncAssertStates(t *testing.T, c *http.Client, baseURL string, libID int64) {
	t.Helper()
	ready := asyncItemsByStatus(t, c, baseURL, asyncToken, libID, "ready")
	if len(ready) != 2 {
		t.Fatalf("AC-states: ?status=ready returned %d items, want 2 (the TV-parsed files); got %v", len(ready), asyncPaths(ready))
	}
	for _, it := range ready {
		if it.Status != "ready" {
			t.Errorf("AC-states: ?status=ready returned %q with status %q", it.RelativePath, it.Status)
		}
	}
	pending := asyncItemsByStatus(t, c, baseURL, asyncToken, libID, "pending")
	if len(pending) == 0 {
		t.Errorf("AC-states: ?status=pending returned 0 items post-drain; want the corrupt fixture (tv-parser skips non-TV)")
	}
}

// asyncDeriveShow independently extracts (title, season, episode) from a TV-style
// filename stem, NOT via the plugin's parseTV (reviewer-independence). It scans
// bytes for the ASCII "S<digits>E<digits>" token (Cyrillic bytes are >=0x80 so
// they never match), derives season/episode directly, and normalizes the prefix's
// "."/"_" separators to spaces for the title. Stdlib only.
func asyncDeriveShow(stem string) (title string, season, episode int, ok bool) {
	up := strings.ToUpper(stem)
	sIdx := -1
	for i := 0; i+1 < len(up); i++ {
		if up[i] == 'S' && up[i+1] >= '0' && up[i+1] <= '9' {
			sIdx = i
			break
		}
	}
	if sIdx < 0 {
		return "", 0, 0, false
	}
	j := sIdx + 1
	for j < len(up) && up[j] >= '0' && up[j] <= '9' {
		season = season*10 + int(up[j]-'0')
		j++
	}
	if j >= len(up) || up[j] != 'E' {
		return "", 0, 0, false
	}
	j++
	for j < len(up) && up[j] >= '0' && up[j] <= '9' {
		episode = episode*10 + int(up[j]-'0')
		j++
	}
	title = strings.NewReplacer(".", " ", "_", " ").Replace(stem[:sIdx])
	title = strings.Join(strings.Fields(strings.Trim(title, "- ")), " ")
	return title, season, episode, true
}

// asyncItemsByStatus lists items filtered by status via the unchanged ?status=
// handler (S9). It builds the URL with strconv (no fmt) to keep imports within the
// black-box allowlist.
func asyncItemsByStatus(t *testing.T, c *http.Client, baseURL, token string, libID int64, status string) []itemDTO {
	t.Helper()
	var resp itemsResponse
	url := baseURL + "/api/v1/items?library=" + strconv.FormatInt(libID, 10) + "&status=" + status + "&limit=200"
	if st := doRequest(t, c, http.MethodGet, url, token, nil, &resp); st != http.StatusOK {
		t.Fatalf("list items status=%s: HTTP %d, want 200", status, st)
	}
	return resp.Items
}

// asyncDoc is the navigated slice of the enriched document the golden asserts over
// (parsed base fields + the enrichment output: sources/_provenance/_view/_stages).
type asyncDoc struct {
	Parsed     map[string]any            `json:"parsed"`
	Ffprobe    json.RawMessage           `json:"ffprobe"`
	Sources    map[string]map[string]any `json:"sources"`
	Provenance map[string]map[string]any `json:"_provenance"`
	View       map[string]map[string]any `json:"_view"`
	Stages     []map[string]any          `json:"_stages"`
}

func parseAsyncDoc(t *testing.T, raw json.RawMessage) asyncDoc {
	t.Helper()
	var d asyncDoc
	if err := json.Unmarshal(raw, &d); err != nil {
		t.Fatalf("unmarshal document: %v (doc=%s)", err, raw)
	}
	return d
}

// asyncStageHas reports whether stages has an entry for plugin with the given status.
func asyncStageHas(stages []map[string]any, plugin, status string) bool {
	for _, s := range stages {
		if asyncStr(s, "plugin_id") == plugin && asyncStr(s, "status") == status {
			return true
		}
	}
	return false
}

// asyncHasDupStage reports whether two stages share both plugin_id and started_at
// (the within-item double-processing signature the lease prevents).
func asyncHasDupStage(stages []map[string]any) bool {
	seen := make(map[string]bool, len(stages))
	for _, s := range stages {
		key := asyncStr(s, "plugin_id") + "|" + asyncStr(s, "started_at")
		if key == "|" {
			continue // no identifying fields -> cannot classify as a duplicate
		}
		if seen[key] {
			return true
		}
		seen[key] = true
	}
	return false
}

func asyncPaths(items []itemDTO) []string {
	out := make([]string, 0, len(items))
	for _, it := range items {
		out = append(out, it.RelativePath)
	}
	return out
}

// asyncStr reads a string field from a decoded JSON map.
func asyncStr(m map[string]any, k string) string { s, _ := m[k].(string); return s }

// asyncInt reads a JSON numeric field (structpb emits numbers as float64); -1 = absent.
func asyncInt(m map[string]any, k string) int {
	f, ok := m[k].(float64)
	if !ok {
		return -1
	}
	return int(f)
}
